// Уборка после rc-02…rc-05 и проверка удаления (F-92 AC1 / F-91 AC4), как 11.10.2026 17:45 на iPhone:
// админка приложения → קטע → «הסרת ההקראה» → окно «להסיר את ההקראה?» → «הסרת ההקראה» → «לקטע הזה אין עדיין הקראה.»;
// у пользователя снова «אין הקראה לקטע הזה», «השמע» неактивна.
// Удаляет записи ТОЛЬКО тестовых קטעים: ערבית אשכנז «המעריב ערבים», «אהבת עולם», תהילים ל״ט. Нет записи — шаг пропускается.
// Отличие от specs/admin/ad-07 (Android-only, удаляет одну свою запись): уборка всех записей прогона, работает на iOS.
import { $$, driver, expect } from '@wdio/globals';
import { byText, scrollToText } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';
import { asAdmin, openAdminHome, openAdminPrayer, openSection, openUserArvit3, REC_CARD, REC_NONE, REC_REMOVE_BTN } from '../_lib/admin.ts';
import { playerButton, recordingLine, shown, typeSearch } from '../_lib/app-0710.ts';

/** «הסרת ההקראה» на экране קטע + подтверждение в окне (у кнопки окна тот же текст — берём верхнюю). Нет записи → false. */
async function removeRecordingHere() {
  await scrollToText(REC_CARD);
  if (!(await shown(byText(REC_REMOVE_BTN)))) await scrollToText(REC_REMOVE_BTN).catch(() => {});
  if (!(await shown(byText(REC_REMOVE_BTN)))) return false;
  await (await byText(REC_REMOVE_BTN)).click();
  await (await byText('להסיר את ההקראה?')).waitForDisplayed({ timeout: 10000 });
  const btns = driver.isAndroid
    ? await $$(`//*[@text="${REC_REMOVE_BTN}"]`)
    : await $$(`-ios predicate string:label == "${REC_REMOVE_BTN}" AND visible == 1`);
  let topIdx = 0, topY = Infinity;
  const n = await btns.length;
  for (let i = 0; i < n; i++) { const y = Number(await btns[i].getLocation("y")); if (y < topY) { topY = y; topIdx = i; } }
  await btns[topIdx].click();
  await expect(await byText(REC_NONE)).toBeDisplayed({ wait: 20000 });
  return true;
}

describe('Озвучка: удаление тестовых записей', () => {
  afterEach(async () => { await toHome(); });

  it('RC-06 «הסרת ההקראה» для ערבית אשכנז קטע 3/4 и תהילים ל״ט → у пользователя «אין הקראה» #6a86f7eda7b2 @data @cleanup', async () => {
    await asAdmin();
    for (const title of ['המעריב ערבים', 'אהבת עולם']) {
      await openAdminPrayer('ערבית', 'אשכנז');
      await openSection(title);
      await removeRecordingHere();
      await toHome();
    }
    // תהילים ל״ט: карточка без נוסח («תהילים ל״ט, N מתוך 1 קטעים מאושרים») — через поиск админки «ל״ט».
    await openAdminHome();
    await typeSearch('ל״ט');
    await (await byText('תהילים ל״ט')).click();                                   // TODO калибровка: на iOS текст карточки склеен — при падении искать label, начинающийся с «תהילים ל״ט,»
    await openSection('למנצח לידותון מזמור');                                     // с 22.10 (#56d002bd); было «למנצח לידיתון [לידותון]»
    await removeRecordingHere();

    // Пользователь: стр.3 ערבית אשכנז — записи нет.
    await toHome();
    await openUserArvit3();
    await scrollToText('האזן להקראה');
    await expect(byText('אין הקראה לקטע הזה')).toBeDisplayed();
    await expect(recordingLine()).not.toBeDisplayed();
    await expect(await playerButton('השמע')).toBeDisabled();
  });
});
